               </figure>

               <div class="dialog-actions">
                 <button type="submit" value="cancel" class="secondary" id="cancel-delete">Cancel</button>
                 <button type="submit" value="delete" class="danger" id="confirm-delete-action">Delete</button>
               </div>
             </form>
           </dialog>
         `;
       }

       const main = document.querySelector('#main');
