       const dialog = document.querySelector('#confirm-delete');
       const trigger = document.querySelector('#open-delete');
       const status = document.createElement('p');
       status.className = 'status';
       status.setAttribute('aria-live', 'polite');
       status.id = 'status-message';
       status.textContent = 'No changes yet.';
       main.querySelector('.shell').appendChild(status);

       const cancelButton = document.querySelector('#cancel-delete');

       trigger.addEventListener('click', () => {
         dialog.showModal();
         cancelButton.focus();
         document.body.classList.add('modal-open');
       });

       dialog.addEventListener('close', () => {
         document.body.classList.remove('modal-open');
         if (dialog.returnValue === 'delete') {
           status.textContent = 'Image deleted from your library.';
