const path = require('path');
(async () => {
  const browser = await chromium.launch({ executablePath: '/usr/bin/chromium', args: ['--no-sandbox'] });
  const page = await browser.newPage({ viewport: { width: 1280, height: 900 } });
  await page.goto('file://' + path.resolve('index.html'));

  const checks = {};
  checks.dialogClosedByDefault = await page.locator('#confirm-delete').evaluate(el => !el.open);
  checks.triggerHasClass = await page.locator('button.trigger').count();
  checks.triggerName = await page.locator('#open-delete').textContent();

  await page.addScriptTag({ path: '/tmp/a11ydeps/node_modules/axe-core/axe.min.js' });
  const closedAxe = await page.evaluate(async () => await window.axe.run(document));
  await page.locator('#open-delete').click();
  await page.waitForFunction(() => document.querySelector('#confirm-delete')?.open === true);
  checks.focusOnOpen = await page.evaluate(() => document.activeElement && document.activeElement.id);
  const openAxe = await page.evaluate(async () => await window.axe.run(document));

  await page.keyboard.press('Escape');
  await page.waitForFunction(() => document.querySelector('#confirm-delete')?.open === false);
  checks.focusRestored = await page.evaluate(() => document.activeElement && document.activeElement.id);

  const violations = [...closedAxe.violations, ...openAxe.violations].filter(v => !v.tags.includes('best-practice'))
    .map(v => ({ id: v.id, impact: v.impact, targets: v.nodes.map(n => n.target) }));

  console.log(JSON.stringify({ checks, violations }, null, 2));
  await browser.close();
  process.exit(violations.length ? 1 : 0);
})();
